claude-ox () 
{ 
    local attempt=1 max_attempts=3 args=("$@") start end elapsed status;
    while (( attempt <= max_attempts )); do
        start=$(date +%s);
        env ANTHROPIC_BASE_URL="https://openrouter.ai/api" ANTHROPIC_AUTH_TOKEN="$OPENROUTER_API_KEY" ANTHROPIC_API_KEY="" CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY=1 CLAUDE_CODE_MAX_CONTEXT_TOKENS=1000000 claude --model stealth/ox-alpha --fallback-model claude-sonnet-5,claude-opus-4-8 "${args[@]}";
        status=$?;
        end=$(date +%s);
        elapsed=$(( end - start ));
        if (( status == 0 )); then
            return 0;
        fi;
        if (( elapsed < 15 && attempt < max_attempts )); then
            echo "claude-ox: exited abnormally after ${elapsed}s (attempt $attempt/$max_attempts) — reattaching with --continue..." 1>&2;
            args=(--continue);
            attempt=$(( attempt + 1 ));
            sleep 2;

